class Reassembler:
    def __init__(self):
        self._state = 'sync'      # 'sync' | 'len' | 'payload' | 'check'
        self._saw_aa = False
        self._len_buf = bytearray()
        self._length = 0
        self._payload = bytearray()

    def feed(self, chunk: bytes) -> list:
        out = []
        for b in chunk:
            if self._state == 'sync':
                if self._saw_aa:
                    if b == 0x55:
                        self._state = 'len'
                        self._len_buf = bytearray()
                        self._saw_aa = False
                    elif b == 0xAA:
                        pass  # remain pending on 0xAA
                    else:
                        self._saw_aa = False
                elif b == 0xAA:
                    self._saw_aa = True
            elif self._state == 'len':
                self._len_buf.append(b)
                if len(self._len_buf) == 2:
                    self._length = self._len_buf[0] | (self._len_buf[1] << 8)
                    if self._length > 4096:
                        self._resync()
                    else:
                        self._payload = bytearray()
                        self._state = 'check' if self._length == 0 else 'payload'
            elif self._state == 'payload':
                self._payload.append(b)
                if len(self._payload) == self._length:
                    self._state = 'check'
            else:  # 'check'
                x = 0
                for p in self._payload:
                    x ^= p
                if b == x:
                    out.append(bytes(self._payload))
                self._resync()
        return out

    def _resync(self):
        self._state = 'sync'
        self._saw_aa = False
        self._len_buf = bytearray()
        self._payload = bytearray()
        self._length = 0
